{
  "findings": [
    {
      "title": "Incomplete sentence in Section 11.5",
      "page": 91,
      "quote": "once all patients in the study have completed the 16-week treatment period.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 10.2.4",
      "page": 89,
      "quote": "TEAEs by severity (according to the grading scale outlined in Section 10.2.4 )",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 15.1",
      "page": 92,
      "quote": "Investigator and sponsor responsibilities surrounding the premature termination of a study are presented in Section 15.1.",
      "severity": "major"
    },
    {
      "title": "Incomplete sentence in Section 11.4.3.2",
      "page": 88,
      "quote": "baseline to week 16) will be analyzed using an analysis of covariance (ANCOVA) model for the FAS",
      "severity": "major"
    },
    {
      "title": "Inconsistent missing data handling for primary endpoint",
      "page": 87,
      "quote": "Treatment policy strategy: Data collected after the patient discontinued treatment will be included in the analysis.",
      "severity": "major"
    },
    {
      "title": "Inconsistent missing data handling for key secondary endpoint",
      "page": 88,
      "quote": "Treatment policy strategy: Data collected after the patient discontinued treatment will be included in the analysis.",
      "severity": "major"
    },
    {
      "title": "Inconsistent definition of treatment-emergent period",
      "page": 89,
      "quote": "The treatment-emergent period is defined as the day from first dose of study drug to end of study.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of follow-up period",
      "page": 89,
      "quote": "Follow-up period: date after week 16 visit date (study day 113 starting from first dose of study drug if week 16 visit date is unavailable) to end of study.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of treatment-emergent adverse events",
      "page": 89,
      "quote": "Treatment-emergent adverse events are defined as those that are not present at baseline or represent the exacerbation of a pre-existing condition during the treatment-emergent period.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of pre-existing immunoreactivity",
      "page": 91,
      "quote": "Pre-existing immunoreactivity, defined as a positive ADA assay response at baseline, with all post-dose ADA results negative, or a positive assay response at baseline, with all post-dose ADA assay responses less than 4-fold over baseline titer levels",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of treatment-boosted ADA response",
      "page": 91,
      "quote": "Treatment boosted ADA response, defined as any post-dose positive ADA assay response that is 4-fold over baseline titer levels when baseline is positive in the ADA assay",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of NAb analysis set",
      "page": 86,
      "quote": "The NAb analysis set includes all patients who received any study drug and who are negative in the ADA assay or with at least 1 non-missing result in the NAb assay (patients who are ADA negative are set to negative in the NAb analysis set).",
      "severity": "minor"
    }
  ]
}
